package com.hs.jxc.sys.service;

import com.hs.jxc.common.api.*;
import com.hs.jxc.sys.api.*;
import java.util.*;
import org.springframework.context.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;

/** Configuration-only snapshots. People and concrete approver identities are never template data. */
@Configuration
public class SystemTemplateStructures {
    @Bean TemplateStructureContributor roleTemplates(JdbcTemplate jdbc,JsonCodec json){return new TemplateStructureContributor(){
        public String key(){return "role-templates";}public String itemType(){return "ROLE_TEMPLATE";}public String label(){return "角色权限结构（不含人员绑定）";}public boolean requiresReview(){return true;}
        public Map<String,Object>snapshot(Access source){var roles=new ArrayList<Map<String,Object>>();for(var raw:jdbc.queryForList("SELECT code,name,role_type,permissions,field_policies FROM sys_role WHERE country_id=? AND code NOT IN('COUNTRY_ADMIN','SUPER') AND role_type<>'COUNTRY_ADMIN' ORDER BY code",source.requireCountry())){var permissions=SystemManagementService.strings(json.read(String.valueOf(raw.get("permissions")),List.class));if(permissions.stream().anyMatch(p->p.contains("*")||Set.of("sys:country:create","sys:country:activate","sys:template:publish","sys:cross-country:view").contains(p)))continue;roles.add(Map.of("code",raw.get("code"),"name",raw.get("name"),"roleType",raw.get("role_type"),"permissions",permissions,"fieldPolicies",json.readMap(String.valueOf(raw.get("field_policies")))));}return Map.of("roles",roles);}
        @SuppressWarnings("unchecked") public void apply(Access target,Map<String,Object>payload,long item){for(var row:(List<Map<String,Object>>)payload.getOrDefault("roles",List.of())){var permissions=SystemManagementService.strings(row.get("permissions"));var policies=(Map<String,Object>)row.getOrDefault("fieldPolicies",Map.of());if(permissions.stream().anyMatch(p->!target.has(p)))throw ApiException.forbidden();for(var field:policies.entrySet())if(!FieldPolicyService.GROUPS.contains(field.getKey())||FieldPolicyService.rank(String.valueOf(field.getValue()))>FieldPolicyService.rank(target.fieldGroups().get(field.getKey())))throw ApiException.forbidden();jdbc.update("INSERT INTO sys_role(country_id,code,name,role_type,status,permissions,field_policies) VALUES(?,?,?,?,'DISABLED',?::jsonb,?::jsonb) ON CONFLICT(country_id,code) DO NOTHING",target.requireCountry(),row.get("code"),row.get("name"),row.get("roleType"),json.write(permissions),json.write(policies));}}
        // Roles remain disabled until explicitly enabled through the original role management command.
        public boolean ready(Access target,long item){return true;}
    };}
    @Bean TemplateStructureContributor approvalStructure(JdbcTemplate jdbc,JsonCodec json){return new TemplateStructureContributor(){
        public String key(){return "approval-structure";}public String itemType(){return "APPROVAL_RULE";}public String label(){return "审批规则版本结构（人员须当地配置）";}public boolean requiresReview(){return true;}
        public Map<String,Object>snapshot(Access source){var rules=new ArrayList<Map<String,Object>>();for(var raw:jdbc.queryForList("SELECT doc_type,name,priority,conditions,nodes,version_no FROM wf_rule WHERE country_id=? AND status='ACTIVE' ORDER BY rule_key,version_no",source.requireCountry())){var nodes=new ArrayList<Map<String,Object>>();for(Object node:json.read(String.valueOf(raw.get("nodes")),List.class)){var map=(Map<?,?>)node;Map<String,Object>safe=new LinkedHashMap<>();for(String key:List.of("seq","nodeName","approverType","mode"))safe.put(key,map.get(key));if("ROLE".equals(map.get("approverType")))safe.put("approverRef",map.get("approverRef"));else safe.put("requiresLocalApprover",true);nodes.add(safe);}rules.add(Map.of("docType",raw.get("doc_type"),"name",raw.get("name"),"priority",raw.get("priority"),"conditions",json.read(String.valueOf(raw.get("conditions")),List.class).stream().map(v->{var condition=(Map<?,?>)v;return Map.of("field",condition.get("field"),"op",condition.get("op"),"requiresLocalValue",true);}).toList(),"nodes",nodes,"versionNo",raw.get("version_no")));}var configs=jdbc.queryForList("SELECT doc_type,approval_required,key_fields FROM wf_doc_type_config WHERE country_id=? ORDER BY doc_type",source.requireCountry()).stream().map(r->Map.of("docType",r.get("doc_type"),"approvalRequired",r.get("approval_required"),"keyFields",json.read(String.valueOf(r.get("key_fields")),List.class))).toList();return Map.of("rules",rules,"docTypes",configs);}
        @SuppressWarnings("unchecked") public void apply(Access target,Map<String,Object>payload,long item){for(var row:(List<Map<String,Object>>)payload.getOrDefault("rules",List.of())){String key="TPL-"+item+"-"+String.valueOf(row.get("docType"));int existing=jdbc.queryForObject("SELECT count(*) FROM wf_rule WHERE country_id=? AND rule_key=?",Integer.class,target.requireCountry(),key);if(existing==0)jdbc.update("INSERT INTO wf_rule(country_id,rule_key,doc_type,name,priority,conditions,nodes,version_no,status,created_by) VALUES(?,?,?,?,?,?::jsonb,?::jsonb,?,'DRAFT',?)",target.requireCountry(),key,row.get("docType"),row.get("name"),row.get("priority"),json.write(row.get("conditions")),json.write(row.get("nodes")),row.get("versionNo"),target.userId());}for(var cfg:(List<Map<String,Object>>)payload.getOrDefault("docTypes",List.of()))jdbc.update("INSERT INTO wf_doc_type_config(country_id,doc_type,approval_required,key_fields) VALUES(?,?,true,?::jsonb) ON CONFLICT(country_id,doc_type) DO NOTHING",target.requireCountry(),cfg.get("docType"),json.write(cfg.get("keyFields")));}
        public boolean ready(Access target,long item){return jdbc.queryForObject("SELECT count(*) FROM wf_rule WHERE country_id=? AND rule_key LIKE ? AND status='DRAFT'",Integer.class,target.requireCountry(),"TPL-"+item+"-%")==0;}
        public void confirm(Access target,long item,String comment){if(!ready(target,item))throw new ApiException(409,"SYS_CONFIG_MISSING","请在审批规则页面配置当地审批人并启用复制的审批草稿");}
    };}
}
